    // 1. Null check for output pointers
    if ((minimum_margin == NULL) || (limiting_index == NULL) || 
        (momentum == NULL) || (reserve_vector == NULL)) {
        return ADCS_E_NULL;
    }

    // 2. Initialize outputs
    *minimum_margin = INFINITY;
    *limiting_index = SIZE_MAX;
    *momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    *reserve_vector = (adcs_vec3_t){0.0, 0.0, 0.0};

    // 3. Null check for input arrays
    if ((wheels == NULL) || (speed_limits == NULL)) {
        return ADCS_E_NULL;
    }

    // 4. Range check for count
    if ((count < 1) || (count > 16)) {
        return ADCS_E_RANGE;
    }

    adcs_vec3_t norm_axis;
    double margin_i;
    adcs_vec3_t term;
    size_t i;

    // 5. Iterate and validate each wheel
    for (i = 0; i < count; i++) {
        // Check speed limit: nonfinite or nonpositive
        if ((!isfinite(speed_limits[i])) || (speed_limits[i] <= 0.0)) {
            return ADCS_E_RANGE;
        }

        // Check inertia: nonfinite or nonpositive
        if ((!isfinite(wheels[i].inertia_kg_m2)) || (wheels[i].inertia_kg_m2 <= 0.0)) {
            return ADCS_E_RANGE;
        }

        // Check speed: nonfinite
        if (!isfinite(wheels[i].speed_rad_s)) {
            return ADCS_E_RANGE;
        }

        // Check axis: norm <= ADCS_EPS_NORM or nonfinite
        if (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &norm_axis) != ADCS_OK) {
            return ADCS_E_RANGE;
        }

        // Calculate margin: speed_limits[i] - |speed_rad_s_i|
        margin_i = speed_limits[i] - fabs(wheels[i].speed_rad_s);

        // Update minimum margin and limiting index (first index of smallest margin)
        if (margin_i < *minimum_margin) {
            *minimum_margin = margin_i;
            *limiting_index = i;
        }

        // Accumulate reserve vector: sum(inertia_i * margin_i * normalize(axis_i))
        term = adcs_vec3_scale(&norm_axis, wheels[i].inertia_kg_m2 * margin_i);
        *reserve_vector = adcs_vec3_add(reserve_vector, &term);
    }

    // 6. Calculate current linked-library cluster momentum
    // Inputs have been validated, so this should succeed.
    adcs_wheel_momentum(wheels, count, momentum);

    return ADCS_OK;
}

